We start by proving the following auxiliary statement:

\begin{restatable}{lemma}{lemmatail}[Tail-bound]\label{lem:tail_bound}
Let $\varphi\in(0,1)$ and $\epsilon \leq \frac{\varphi^2}{100}$, and let $G=(V,E)$ be a $d$-regular graph that admits $(k,\varphi,\e)$-clustering $C_1, \ldots, C_k$.   Let $L$ be the normalized Laplacian of $G$. Let $u$ be a normalized eigenvector of $L$ with $||u||_2=1$ and with eigenvalue at most $2\epsilon$.  Then for any $\beta>1$ we have \[
\frac1{n}\cdot\biggl|
\left \{x\in V: |u(x)|\geq \beta\cdot \sqrt{\frac{10}{\min_{i\in [k]}|C_i|}} \right \}\biggl| \leq \left(\frac{\beta}{2}\right) ^{-{\varphi^2/20\cdot\epsilon}}\text{.}\]
\end{restatable}
\begin{proof}
Let $s_{\min}=\min_{i\in \{1,\dots,k\}}|C_i|$. We define 
\[S^{+}=\left\{x\in V: u(x) \geq \beta\cdot\sqrt{\frac{10}{s_{\min}}}\right\}\text{,}\]
and
\[S^{-}=\left\{x\in V: -u(x) \geq \beta\cdot\sqrt{\frac{10}{s_{\min}}}\right\}\]
Note that $-u$ is also an eigenvector of $L$ with the same eigenvalue as $u$, hence, without loss of generality suppose that $|S^{+}|\geq |S^{-}|$. Let $T=\left\{x\in V: u(x)^2 \geq \frac{10}{s_{\min}}\right\}\text{.}$ Since, $1=\|u\|^2_2 = \sum_{x\in V} u(x)^2$, an averaging argument implies $|T|\leq \frac{s_{\min}}{10}$.  Let 
\[T^{+}=\left\{x\in V: u(x) \geq \sqrt{\frac{10}{s_{\min}}}\right\}\text{.}\]
Note that $\beta>1$, hence, ${S^{+}} \subseteq {T^{+}} \subseteq T$, and so we have $|{S^{+}}| \leq |T^+|\leq|T|\leq \frac{s_{\min}}{10}$.
We may assume that $S^{+}$ is non-empty as otherwise the lemma follows immediately. Let $\theta_{0}=\beta\cdot\sqrt{\frac{10}{s_{\min}}}$. Note that $S^{+}=S(\theta_0)$. Hence, $1\leq |S(\theta_{0})|\leq \frac{s_{\min}}{10}$.  Therefore by Lemma \ref{lem:concentrationnearboundary} there exists a threshold $\theta_1$  such that
\begin{equation}
\label{1eq:thet0}
\left(1 - \frac{8\epsilon}{\varphi}\right)\beta\cdot\sqrt{\frac{10}{s_{\min}}} \leq \theta_1 \leq \beta\cdot\sqrt{\frac{10}{s_{\min}}}\text{, and}
\end{equation}
\[
\frac{p(\theta_1)}{|S(\theta_1)|} \leq 2\theta_1\text{.}\] 
For any $t\geq 1$ we define $\theta_{t+1}=\theta_t(1-\frac{8\epsilon}{\varphi})$. For some $t'\geq 0$ we must have $\theta_{t'+1}\leq \sqrt{\frac{10}{s_{\min}}} \leq \theta_{t'}$.

Thus by \eqref{1eq:thet0} we have
\begin{equation}
\label{1eq:theta-t-lwb}
\theta_{t'} = \left(1-\frac{8\epsilon}{\varphi}\right)^{t'-1}\theta_1 \geq \left(1-\frac{8\epsilon}{\varphi}\right)^{t'}\cdot\beta\cdot\sqrt{\frac{10}{s_{\min}}} \text{,}
\end{equation}
and
\begin{equation}
\label{1eq:theta-t-upb}
\theta_{t'}\leq \frac{\theta_{t'+1}}{\left(1-\frac{8\epsilon}{\varphi}\right)} \leq \frac{\sqrt{\frac{10}{s_{\min}}}}{\left(1-\frac{8\epsilon}{\varphi}\right)}
\end{equation}
Putting~\eqref{1eq:theta-t-lwb} and ~\eqref{1eq:theta-t-upb} together we get 
\begin{equation}
\label{e:t0up}
\beta \leq  \left(1-\frac{8\epsilon}{\varphi}\right)^{-
t'-1}
\end{equation}
Recall that for all $t\geq 1$ we have $\theta_{t+1}=\theta_t(1-\frac{8\epsilon}{\varphi})$, thus 
\[S^{+}={S(\theta_0)} \subseteq {S(\theta_1)} \subseteq {S(\theta_2)} \subseteq \ldots \subseteq S(\theta_{t'})\subseteq T^{+}\text{.} \]
Therefore for all $0\leq t\leq t'$ we have
\begin{equation}
\label{1eq:S_i-size}
|S^{+}|\leq |S(\theta_t)|\leq |T^{+}|\leq \frac{s_{\min}}{10} \text{.}
\end{equation}
Since $|S(\theta_t)|\leq \frac{\min_{i\in\{1,\dots,k\}}|C_i|}{10}=\frac{s_{\min}}{10}$, by Lemma~\ref{lem:maintool} for all $1\leq t\leq t'$ we have 
\begin{equation}
\label{1eeq:S_i+1-size}
|S(\theta_{t+1})|\geq |S(\theta_t)| \left(1+\frac{\varphi}{2}\right) \text{.}
\end{equation}
Therefore 
\begin{align}
t'&\leq \log_{1+\frac{\varphi}{2}}\left(\frac{|T^{+}|}{|S^{+}|}\right) &&\text{By \eqref{1eeq:S_i+1-size}} \nonumber\\ 
&\leq \log_{1+\frac{\varphi}{2}}\left(\frac{s_{\min}}{10\cdot|S^{+}|}\right)  &&\text{By \eqref{1eq:S_i-size}} \nonumber \\
&\leq \log_{1+\frac{\varphi}{2}}\left(\frac{s_{\min}}{5\cdot|S^+\cup S^-|}\right) &&\text{By the assumption }|S^{+}|\geq |S^{-}| \label{e:t0lw}
\end{align}
Putting \eqref{e:t0up} and \eqref{e:t0lw} together we get
\begin{align}
\beta &\leq  \left(1-\frac{8\epsilon}{\varphi}\right)^{-
t'-1} &&\text{By \eqref{e:t0up}} \nonumber \\
&\leq \left(1-\frac{8\epsilon}{\varphi}\right)^{-1-
\log_{1+\frac{\varphi}{2}}\left(\frac{s_{\min}}{5\cdot |S^+\cup S^-|}\right)}  &&\text{By \eqref{e:t0lw}} \nonumber \\
&\leq 2\cdot \left(\frac{s_{\min}}{5\cdot |S^+\cup S^-|} \right)^{-
\log_{1+\frac{\varphi}{2}}\left( 1-\frac{8\epsilon}{\varphi} \right)}  &&\text{Since }\frac{\epsilon}{\varphi^2}\leq \frac{1}{100} \label{eq-tail-beta-bnd}
\end{align}
Note that for any $x\in \R$ we have $1+x\leq e^x$, and for any $x<0.01$ we have $1-x\geq e^{-1.2 x}$, thus given $\frac{\epsilon}{\varphi}<0.01$ we have 
\begin{equation}
{\log_{1+\frac{\varphi}{2}}\left( 1-\frac{8\epsilon}{\varphi} \right)}=\frac{\ln \left( 1-\frac{8\epsilon}{\varphi} \right)}{\ln \left(1+\frac{\varphi}{2} \right)} \geq \frac{-\frac{10\epsilon}{\varphi}}{\frac{\varphi}{2}}\geq -\frac{20\cdot\epsilon}{\varphi^2} \label{eq-power-bnd}  
\end{equation}
Putting \eqref{eq-tail-beta-bnd} and \eqref{eq-power-bnd} together we get
\[\frac{\beta}{2}\leq \left(\frac{s_{\min}}{5\cdot|S^+\cup S^-|}\right)^{(20\cdot\epsilon / \varphi^2)} \]
Therefore we have
\[ |S^+\cup S^-| \leq s_{\min}\cdot \left(\frac{\beta}{2}\right)^{-\left(\varphi^2/20\cdot\epsilon\right)}\leq n\cdot \left(\frac{\beta}{2}\right)^{-\left(\varphi^2/20\cdot\epsilon\right)} \text{.}\]


\end{proof}

With the above in mind, we are now ready to prove the main statement:

\begin{proof}
We define \[S=\left \{x\in V: |u(x)|\geq n^{20\epsilon /\varphi^2}\cdot \sqrt{\frac{160}{\min_{i\in k}|C_i|}}\right \}\]
Let $\beta= 4\cdot n^{20\epsilon /\varphi^2}$.
By Lemma \ref{lem:tail_bound} we have
\begin{align*}
|S|&\leq n\cdot\left( \frac{\beta}{2}\right) ^{-{\varphi^2/20\cdot \epsilon}}  \leq  n\cdot \left(2\cdot 
n^{20\epsilon /\varphi^2}\right)^{-{\varphi^2/20\cdot\epsilon}} <  1
\end{align*}
Therefore $S=\emptyset$, hence 
\[\|u\|_\infty \leq n^{20\epsilon /\varphi^2}\cdot \sqrt{\frac{160}{\min_{i\in k}|C_i|}} \text{.} \]
\end{proof}
